"""Versioned OpenRouter route boundary for prospective RPI investigations.

The chronology validator below is an explicit copy of rpi_prospective.validate
with only its policy-identity block replaced. Native scientific-store verification
is reused unchanged. Original API files establish observed route continuity, not
retained weights, provider internals, physical validity or training admission.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
import sqlite3
import subprocess
from datetime import UTC, datetime
from pathlib import Path

from . import rpi_prospective as legacy
from .contracts import canonical, check_physical_forecast_source, digest
from .evaluation import (
    measurement_definition_check,
    measurement_stage_check,
    quality_review_exclusion,
)
from .rpi_prospective import (
    ASSESSMENT_CONTRACT,
    EXCLUDED_INPUTS,
    SOURCE_KINDS,
    STAGES,
    _ids,
    _target,
    _time,
)

SCHEMA = "rpi-prospective-glm-api-v1"
RUNTIME_SCHEMA = "rpi-openrouter-route-runtime-v1"
PREFIX_SCHEMA = "rpi-openrouter-commitment-prefix-v1"
LEGACY_SHA256 = 'f58db4c8ad20aa020fd5f8b7199709c94cced7b1fdc97a53024b7034e3e4141c'
MODEL = "z-ai/glm-5.3-flash"
ROUTING = {"only": ["z-ai/fp8"], "order": ["z-ai/fp8"], "allow_fallbacks": False,
           "require_parameters": True, "data_collection": "deny"}
SOURCE_HASHES = {
    "launcher": "822293b286dc556f4f995c869ac429da4c06feeb6c8960103d55a74420efbd42",
    "transport": "2c90698a62fe9a4f1a872a2146ff7c6fe3fb44584fb19bfb054865e57c3f5c8e",
    "dependency_lock": "9cb5ca9140d0b05835ece79ea20ae1dc3a75c52e770af90af5d5692652082a25",
}
POLICY_IDENTITY = {
    "model_family": "GLM-5.3-Flash", "identity_mode": "provider_route",
    "model_id": MODEL, "provider": "OpenRouter", "serving_provider": "Z.AI",
    "route": "z-ai/fp8", "precision": "FP8", "precision_basis": "provider_advertised",
    "checkpoint_id": None, "checkpoint_revision": None, "tokenizer_sha256": None,
    "chat_template_sha256": None, "weight_version": None,
    "retained_base_identity_verified": False,
}


def _need(condition, message):
    if not condition:
        raise ValueError(message)


def _bytes(path):
    path = Path(path)
    _need(path.is_absolute() and path.is_file() and not path.is_symlink(),
          "missing_or_linked_original_api_artifact")
    _need(path.resolve() == path, "linked_api_artifact_ancestor")
    return path.read_bytes()


def _ref(path):
    path = Path(path).resolve(strict=True)
    return {"path": str(path), "sha256": hashlib.sha256(_bytes(path)).hexdigest()}


def _read_ref(ref):
    _need(set(ref) == {"path", "sha256"}, "invalid_original_api_reference")
    raw = _bytes(ref["path"])
    _need(hashlib.sha256(raw).hexdigest() == ref["sha256"], "original_api_artifact_hash_mismatch")
    return json.loads(raw)


def _json_wire_hash(value):
    """Use the production JavaScript serializer; Python float spelling differs."""
    encoded = json.dumps(value, ensure_ascii=True, separators=(",", ":"), allow_nan=False)
    result = subprocess.run(
        ["node", "--input-type=module", "-e",
         ("import fs from 'node:fs'; import crypto from 'node:crypto';"
         "const value=JSON.parse(fs.readFileSync(0,'utf8'));"
         "process.stdout.write(crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex'));")],
        input=encoded, text=True, capture_output=True, timeout=15, check=True,
    )
    return result.stdout


def runtime_receipt(pi_directory, campaign_directory, reviewer, *, fixture_only=False,
                    agents_directory=None):
    """Bind an already-created native run before its prospective commitment.

No inference occurs. The launcher must have written session/launch records;
qualified_at is the actual owner qualification time, never backdated. This
receipt belongs in branch.policy via its digest before the native commitment.
Installed packages use an explicit agents_directory for the pinned Node sources.
"""
    pi = Path(pi_directory).resolve(strict=True)
    campaign = Path(campaign_directory).resolve(strict=True)
    launches = sorted(pi.glob("launch_*.json"))
    _need(bool(launches), "native_launch_required")
    source = (Path(agents_directory).resolve(strict=True) if agents_directory is not None
              else Path(__file__).resolve().parents[2] / "agents")
    result = {"schema": RUNTIME_SCHEMA, "fixture_only": fixture_only,
              "identity": POLICY_IDENTITY.copy(), "reviewer": reviewer,
              "qualified_at": datetime.now(UTC).isoformat(),
              "campaign_directory": str(campaign), "pi_directory": str(pi),
              "session": _ref(pi / "session.json"), "launch": _ref(launches[0]),
              "source_files": {key: _ref(source / name) for key, name in (
                  ("launcher", "launch.mjs"), ("transport", "transport.mjs"),
                  ("dependency_lock", "package-lock.json"))},
              "scope": "observed_api_route_only_not_retained_weights"}
    _verify_runtime(result, campaign, pi, fixture_only=fixture_only, allow_unflushed_history=True)
    return result


def _verify_runtime(runtime, campaign_directory, pi_directory, *, fixture_only,
                    allow_unflushed_history=False):
    _need(runtime["schema"] == RUNTIME_SCHEMA, "wrong_api_runtime_schema")
    _need(runtime["identity"] == POLICY_IDENTITY, "wrong_or_overclaimed_api_identity")
    _need(runtime["fixture_only"] is fixture_only, "runtime_fixture_attribution_mismatch")
    _need(bool(runtime["reviewer"]), "api_runtime_reviewer_required")
    _time(runtime["qualified_at"])
    _need(runtime["scope"] == "observed_api_route_only_not_retained_weights", "runtime_scope_overclaim")
    pi = Path(pi_directory).resolve(strict=True)
    campaign = Path(campaign_directory).resolve(strict=True)
    _need(str(pi) == runtime["pi_directory"] and str(campaign) == runtime["campaign_directory"],
          "api_runtime_belongs_to_other_run")
    _need(pi.parent == campaign.parent and pi.name == "pi" and campaign.name == "campaign",
          "api_run_campaign_layout_mismatch")
    _need(not any(pi.glob("*migration*.json")), "cross_policy_or_runtime_migration_not_admitted")
    _need(runtime["session"]["path"] == str(pi / "session.json"), "wrong_native_session_reference")
    launch_path = Path(runtime["launch"]["path"])
    _need(launch_path.parent == pi and launch_path.name.startswith("launch_"),
          "launch_from_another_run")
    session, launch = _read_ref(runtime["session"]), _read_ref(runtime["launch"])
    _need(session["model_id"] == MODEL and session["pi_version"] == "0.85.1", "wrong_native_policy")
    _need(session["campaign"] == str(campaign), "native_session_campaign_mismatch")
    history = Path(session["session_file"])
    _need(history.parent == pi / "pi_sessions", "native_history_from_another_run")
    if not history.is_file():
        # Pi 0.85.1 persists its new history only when the first assistant arrives.
        # Owner qualification may precede that first prompt. Assessment still
        # requires the original completed history and complete capture prefix.
        _need(allow_unflushed_history and not list((pi / "api").glob("request_*.json"))
              and not (pi / "usage.jsonl").exists(), "missing_native_history_after_api_activity")
    _need(set(runtime["source_files"]) == set(SOURCE_HASHES), "api_source_binding_incomplete")
    for key, expected in SOURCE_HASHES.items():
        reference = runtime["source_files"][key]
        _need(hashlib.sha256(_bytes(reference["path"])).hexdigest() == expected
              and reference["sha256"] == expected, "unqualified_api_" + key)
        field = {"launcher": "launcher_sha256", "transport": "transport_sha256",
                 "dependency_lock": "dependency_lock_sha256"}[key]
        _need(session[field] == expected, "native_source_identity_mismatch")
    _need(_json_wire_hash(launch["config"]) == session["provider_config_sha256"],
          "native_provider_config_hash_mismatch")
    config = launch["config"]
    _need(config["routing"] == ROUTING and config["expected_provider"] == "Z.AI",
          "wrong_api_route_or_fallback")
    _need(config["model"]["id"] == MODEL and config["model"]["provider"] == "openrouter"
          and config["model"]["baseUrl"] == "https://openrouter.ai/api/v1", "wrong_api_endpoint")
    _need(config["common_request"] == {"reasoning": {"effort": "high"}, "temperature": 1,
                                      "max_tokens": 32768}, "api_sampling_changed")
    _need(launch["settings"]["compaction"] == {"enabled": True, "reserveTokens": 32768,
                                               "keepRecentTokens": 20000}, "api_compaction_changed")
    _need(config["model"]["contextWindow"] == 1048576
          and config["model"]["maxTokens"] == 32768, "api_context_changed")
    _need(launch["credentials_in_tools"] is False, "credentials_visible_to_policy")
    for other in pi.glob("launch_*.json"):
        row = json.loads(_bytes(other))
        _need(row["config"] == config and row["settings"] == launch["settings"]
              and row["tool_schema"] == launch["tool_schema"], "run_configuration_changed")
    return session


def _read_sse(path, receipt):
    raw = _bytes(path)
    capture = receipt["response_capture"]
    _need(capture["capture_class"] == "complete_raw_sse" and capture["body_complete"] is True
          and capture["omitted_bytes"] == 0 and capture["omission"] is None,
          "incomplete_original_api_response")
    hashed = hashlib.sha256(raw).hexdigest()
    _need(hashed == capture["retained_sha256"] == receipt["raw_sse_sha256"],
          "original_api_response_hash_mismatch")
    tools, done = {}, False
    models, providers, finishes = set(), set(), set()
    for line in raw.decode().splitlines():
        if not line.startswith("data: "):
            continue
        text = line[6:].strip()
        if text == "[DONE]":
            done = True
            continue
        event = json.loads(text)
        _need(not event.get("error"), "raw_api_error_cannot_be_accepted")
        if "model" in event:
            models.add(event["model"])
        if "provider" in event:
            providers.add(event["provider"])
        _need(event.get("model", MODEL) == MODEL and event.get("provider", "Z.AI") == "Z.AI",
              "raw_response_policy_substitution")
        for choice in event.get("choices", []):
            if choice.get("finish_reason") is not None:
                finishes.add(choice["finish_reason"])
            for item in choice.get("delta", {}).get("tool_calls", []):
                target = tools.setdefault(item["index"], {"id": "", "name": "", "arguments": ""})
                target["id"] += item.get("id", "")
                target["name"] += item.get("function", {}).get("name", "")
                target["arguments"] += item.get("function", {}).get("arguments", "")
    _need(done, "original_response_has_no_terminal_marker")
    _need(models == {MODEL} and providers == {"Z.AI"}, "raw_response_identity_missing")
    _need(bool(finishes) and finishes <= {"stop", "tool_calls", "length"},
          "raw_response_finish_missing_or_invalid")
    return [{**tool, "finish_reasons": sorted(finishes),
             "executable": finishes <= {"tool_calls", "stop"}} for tool in tools.values()]


def capture_prefix(runtime, branch_id, committed_at, *, fixture_only=False):
    """Hash/inspect all original requests through a commitment; later cycles excluded.

This is an owner read of the actual run, not an exporter accepting selected
response paths. No historical prefix from another campaign can authenticate it.
"""
    campaign = Path(runtime["campaign_directory"])
    pi = Path(runtime["pi_directory"])
    _verify_runtime(runtime, campaign, pi, fixture_only=fixture_only)
    cutoff = _time(committed_at)
    _need(_time(runtime["qualified_at"]) <= cutoff, "api_qualification_after_commitment")
    db = sqlite3.connect((campaign / "campaign.sqlite3").as_uri() + "?mode=ro", uri=True)
    try:
        config = json.loads(db.execute("SELECT data FROM meta WHERE key='config'").fetchone()[0])
    finally:
        db.close()
    _need(config["campaign_id"] == branch_id, "api_capture_from_unrelated_campaign")
    _need(config.get("execution_mode") == "physical", "nonphysical_api_campaign")
    _need(bool(config.get("fixture_only")) is fixture_only, "api_campaign_fixture_mismatch")
    records, tool_calls, numbers = [], [], []
    session = _read_ref(runtime["session"])
    launch = _read_ref(runtime["launch"])
    _need(_json_wire_hash(launch["tool_schema"]) == session["tool_schema_sha256"],
          "native_tool_schema_hash_mismatch")
    for path in sorted((pi / "api").glob("request_*.json")):
        request = json.loads(_bytes(path))
        if _time(request["utc"]) > cutoff:
            continue
        body = request["body"]
        numbers.append(int(path.stem.removeprefix("request_")))
        if request["category"] == "investigator":
            systems = [m for m in body["messages"] if m["role"] == "system"]
            _need(len(systems) == 1 and isinstance(systems[0]["content"], str)
                  and hashlib.sha256(systems[0]["content"].encode()).hexdigest()
                  == session["instructions_sha256"], "investigator_instructions_changed")
            expected_tools = [{"type": "function", "function": {**t, "strict": False}}
                              for t in launch["tool_schema"]]
            _need(body.get("tools") == expected_tools, "investigator_tools_changed")
        else:
            _need(request["category"] == "native_compaction_or_summary",
                  "unknown_native_generation_category")
        _need(body["model"] == MODEL and body["provider"] == ROUTING,
              "request_route_changed_or_fallback")
        _need(body["temperature"] == 1 and body["reasoning"] == {"effort": "high"}
              and type(body["max_tokens"]) is int and 0 < body["max_tokens"] <= 32768,
              "request_sampling_changed")
        if request["category"] == "investigator":
            _need(body["max_tokens"] == 32768, "request_sampling_changed")
        else:
            _need(not body.get("tools"), "native_summary_cannot_expose_scientific_tools")
        _need(_json_wire_hash(body) == request["body_sha256"], "original_request_body_hash_mismatch")
        number = path.stem.removeprefix("request_")
        accepted_path = path.parent / f"response_{number}_receipt.json"
        row = {"request": _ref(path), "accounting_id": request["accounting_id"],
               "policy_request_id": request["policy_request_id"]}
        if accepted_path.exists():
            accepted = json.loads(_bytes(accepted_path))
        else:
            accepted = None
        if accepted and accepted.get("output_accepted"):
            _need(_time(request["utc"]) <= _time(accepted["utc"]) <= cutoff,
                  "inflight_or_future_response_at_commitment")
            _need(accepted["accounting_id"] == request["accounting_id"]
                  and accepted["policy_request_id"] == request["policy_request_id"],
                  "api_request_response_identity_mismatch")
            _need(accepted["actual_provider"] == "Z.AI" and accepted["response_model"] == MODEL,
                  "accepted_response_policy_substitution")
            stream = path.parent / accepted["response_capture"]["file"]
            _need(stream.parent == path.parent and stream.name == f"response_{number}.sse",
                  "response_stream_from_another_request")
            calls = _read_sse(stream, accepted)
            tool_calls.extend({**call, "response_receipt": _ref(accepted_path)} for call in calls)
            row.update(status="accepted", response_receipt=_ref(accepted_path), raw_response=_ref(stream))
        else:
            failure_path = path.parent / f"failure_{number}.json"
            failure = json.loads(_bytes(failure_path))
            _need(failure["accounting_id"] == request["accounting_id"]
                  and _time(request["utc"]) <= _time(failure["utc"]) <= cutoff,
                  "unresolved_or_mismatched_api_attempt")
            row.update(status="failed_attempt_retained", failure=_ref(failure_path))
        records.append(row)
    _need(bool(records) and any(r["status"] == "accepted" for r in records), "no_original_api_prefix")
    _need(numbers == list(range(numbers[-1] + 1)), "incomplete_original_request_prefix")
    usage = [json.loads(line) for line in _bytes(pi / "usage.jsonl").decode().splitlines() if line]
    usage = [row for row in usage if _time(row["utc"]) <= cutoff]
    _need(len(usage) == len(records)
          and {(int(r["number"]), r["accounting_id"]) for r in usage}
          == {(n, r["accounting_id"]) for n, r in zip(numbers, records)},
          "api_prefix_disagrees_with_native_accounting")
    history = [json.loads(line) for line in _bytes(session["session_file"]).decode().splitlines()
               if line]
    history = [row for row in history if _time(row["timestamp"]) <= cutoff]
    _need(bool(history) and history[0]["type"] == "session"
          and history[0]["cwd"] == str(pi / "workspace"), "native_history_identity_mismatch")
    native_calls = []
    for row in history:
        if row["type"] == "model_change":
            _need(row["provider"] == "openrouter" and row["modelId"] == MODEL,
                  "native_history_policy_changed")
        message = row.get("message", {})
        if message.get("role") == "assistant":
            _need(message["provider"] == "openrouter" and message["model"] == MODEL,
                  "native_assistant_policy_changed")
            native_calls.extend(c for c in message.get("content", []) if c["type"] == "toolCall")
    original_calls = {c["id"]: c for c in tool_calls}
    _need(len(original_calls) == len(tool_calls), "duplicate_original_api_tool_call")
    _need(len({c["id"] for c in native_calls}) == len(native_calls), "duplicate_native_pi_tool_call")
    _need({c["id"] for c in native_calls} == set(original_calls),
          "api_prefix_disagrees_with_native_tool_history")
    for call in native_calls:
        original = original_calls[call["id"]]
        _need(call["name"] == original["name"], "native_tool_name_differs_from_original_api")
        if original["executable"]:
            _need(call["arguments"] == json.loads(original["arguments"]),
                  "native_tool_arguments_differ_from_original_api")
    return {"schema": PREFIX_SCHEMA, "campaign_directory": str(campaign), "pi_directory": str(pi),
            "branch_id": branch_id, "through_commitment_at": committed_at,
            "records": records, "accepted_tool_calls": tool_calls,
            "native_usage_prefix_sha256": digest(usage),
            "native_history_prefix_sha256": digest(history),
            "scope": "actual_run_prefix_only_route_continuity_not_weight_identity"}


def _validate_api_policy(bundle, require, *, campaign_directory, pi_directory):
    policy, runtime = bundle["branch"]["policy"], bundle["policy_runtime_receipt"]
    require(set(policy) == set(POLICY_IDENTITY) | {"runtime_receipt_sha256"},
            "unknown_or_missing_api_policy_fields")
    require({k: v for k, v in policy.items() if k != "runtime_receipt_sha256"} == POLICY_IDENTITY,
            "wrong_or_overclaimed_api_identity")
    require(digest(runtime) == policy["runtime_receipt_sha256"], "runtime_receipt_hash_mismatch")
    require(campaign_directory is not None and pi_directory is not None,
            "actual_campaign_and_pi_directories_required")
    if campaign_directory is None or pi_directory is None:
        return
    try:
        fixture = bundle.get("fixture_only") is True
        _verify_runtime(runtime, campaign_directory, pi_directory, fixture_only=fixture)
        prefix = capture_prefix(runtime, bundle["branch"]["branch_id"],
                                bundle["decision"]["recorded_at"], fixture_only=fixture)
        require(bundle["api_capture_prefix"] == prefix, "api_commitment_prefix_mismatch")
        matching = []
        for call in prefix["accepted_tool_calls"]:
            if call["name"] != "record_decision" or not call["executable"]:
                continue
            args = json.loads(call["arguments"])
            if args.get("decision") == "prospective_prediction" and args.get("rationale") == bundle["decision"]["rationale"]:
                matching.append(call["id"])
        require(len(matching) == 1 and bool(matching[0]), "prospective_decision_not_in_actual_api_prefix")
    except (OSError, sqlite3.Error, subprocess.SubprocessError) as exc:
        raise ValueError("original_api_records_unavailable:" + str(exc)) from exc


def commitment_binding(branch, evidence, forecast, source, executions):
    """JSON rationale for the existing append-only record_decision tool.

Freeze this exact value in the native decision before any later outcome receipt.
The forecast may concern a later stage on an existing body; no manufacture is
requested and no new specimen identity is fabricated.
"""
    return {"schema": SCHEMA, "branch_sha256": digest(branch),
            "evidence_sha256": digest(evidence), "forecast_sha256": digest(forecast),
            "assessment_contract_sha256": digest(forecast["assessment_contract"]),
            "source_sha256": hashlib.sha256(source.encode()).hexdigest(),
            "executions_sha256": digest(executions)}


def validate(bundle, *, campaign_directory=None, pi_directory=None, allow_fixture=False):
    """Validate integrity and chronology; return per-target outcome eligibility.

Caller must verify the exported records against native stores/receipts. A valid
result is not a numerical score, physical validation, leakage proof, or training
admission. Fixtures require explicit opt-in and can never become physical scores.
"""
    issues = []
    outcomes = []
    fixture = bundle.get("fixture_only") is True
    result = {"schema": SCHEMA, "fixture_only": fixture, "issues": issues,
              "outcomes": outcomes, "physical_score_admissible": False,
              "training_admission": False, "numerical_score": None,
              "scope": "owner-export binding and chronology only"}

    def require(condition, issue):
        if not condition:
            issues.append(issue)

    try:
        canonical(bundle)  # Reject nonfinite values anywhere, including extensions.
        require(bundle["schema"] == SCHEMA, "schema_mismatch")
        require(not fixture or allow_fixture, "fixture_requires_explicit_opt_in")
        branch, evidence = bundle["branch"], bundle["evidence"]
        initial = bundle["initial_evidence"]
        require(bool(initial), "initial_reviewed_packet_required")
        initial_ids, evidence_ids = _ids(initial), _ids(evidence)
        require(branch["initial_evidence_sha256"] == digest(initial), "initial_snapshot_mismatch")
        require(branch["initial_evidence_ids"] == initial_ids, "initial_identity_mismatch")
        require(bool(branch["branch_id"]), "branch_identity_missing")
        require(branch["preserved_investigator"] == "gpt-6-astra", "historical_identity_missing")
        preserved = branch["preserved_state_manifest_sha256"]
        require(len(preserved) == 64 and all(c in "0123456789abcdef" for c in preserved),
                "preserved_state_manifest_missing")
        _validate_api_policy(bundle, require, campaign_directory=campaign_directory,
                             pi_directory=pi_directory)
        require(isinstance(branch["assistance"], list), "assistance_attribution_missing")
        review = branch["input_review"]
        require(bool(review["reviewer"]), "input_review_missing")
        require(set(review["excluded_categories"]) == EXCLUDED_INPUTS, "input_exclusions_incomplete")
        require(bool(branch["public_sources"]), "source_allowlist_empty")
        for item in branch["public_sources"]:
            require(item["kind"] in SOURCE_KINDS, "disallowed_initial_source_category")
            sha = item["sha256"]
            require(len(sha) == 64 and all(c in "0123456789abcdef" for c in sha),
                    "invalid_public_source_hash")
        started = _time(branch["started_at"])
        require(_time(review["reviewed_at"]) <= started, "input_review_after_start")
        for row in initial:
            require(row["origin"] == "physical", "nonphysical_initial_evidence")
            require(_time(row["received_at"]) <= _time(row["released_at"]) <= started,
                    "initialization_before_reviewed_release")
        decision, forecast = bundle["decision"], bundle["forecast"]
        require(forecast["assessment_contract"] == ASSESSMENT_CONTRACT,
                "unknown_or_changed_assessment_contract")
        committed = _time(decision["recorded_at"])
        require(started <= committed, "commitment_before_policy_start")
        require(decision["decision"] == "prospective_prediction", "wrong_decision_record")
        require(decision["evidence_ids"] == evidence_ids, "decision_evidence_ids_mismatch")
        require(decision["evidence_sha256"] == digest(evidence), "decision_evidence_hash_mismatch")
        require(set(initial_ids) <= set(evidence_ids), "initial_packet_missing_from_cutoff")
        current_by_id = {row["evidence_id"]: row for row in evidence}
        for row in initial:
            # A later released correction can mark a row superseded; it cannot
            # silently rewrite its original values, identities or timestamps.
            original = {k: v for k, v in row.items() if k != "superseded"}
            current = {k: v for k, v in current_by_id.get(row["evidence_id"], {}).items()
                       if k != "superseded"}
            require(original == current, "initial_evidence_content_changed")
        releases = {r["delivery_id"]: r for r in bundle["releases"]}
        for row in evidence:
            require(row["origin"] == "physical", "nonphysical_cutoff_evidence")
            require(fixture or not (row.get("fixture_only") or row.get("rehearsal")),
                    "rehearsal_evidence_in_physical_branch")
            require(_time(row["received_at"]) <= _time(row["released_at"]) <= committed,
                    "cutoff_contains_later_evidence")
            release = releases[row["delivery_id"]]
            require(bool(release["reviewer"]) and release["released_at"] == row["released_at"],
                    "cutoff_release_receipt_mismatch")
        source, executions = bundle["source"], bundle["executions"]
        expected = commitment_binding(branch, evidence, forecast, source, executions)
        require(json.loads(decision["rationale"]) == expected, "immutable_decision_binding_mismatch")
        require(bool(executions) and len({e["execution_id"] for e in executions}) == len(executions),
                "distinct_original_execution_receipts_required")
        for execution in executions:
            require(execution["status"] == "ok", "execution_did_not_complete")
            require(execution["hashes"]["executed_source_sha256"] == expected["source_sha256"],
                    "executed_source_mismatch")
            require(execution["result"] == forecast, "executed_forecast_mismatch")
            # Original input text is retained because executor encoding is not
            # assumed to equal the Campaign canonical JSON encoding.
            text = execution["input_text"]
            require(hashlib.sha256(text.encode()).hexdigest() == execution["hashes"]["input_sha256"],
                    "execution_input_hash_mismatch")
            require(json.loads(text)["evidence"] == evidence, "execution_cutoff_mismatch")
        if len(executions) == 2:
            require(executions[0]["hashes"]["input_sha256"] ==
                    executions[1]["hashes"]["input_sha256"], "replay_input_mismatch")
        check_physical_forecast_source(expected["source_sha256"], {"origin": "physical"}, forecast)
        targets = forecast["targets"]
        require(bool(targets), "no_committed_targets")
        by_target = {}
        for target in targets:
            key = _target(target)
            require(key not in by_target, "duplicate_committed_target")
            by_target[key] = target
            require(bool(key[0]) and bool(key[2]) and key[1] in STAGES, "ambiguous_target_identity")
            require(bool(target["unit"]), "missing_target_unit")
            require(isinstance(target["processing_coordinates"], dict)
                    and bool(target["processing_coordinates"]), "missing_processing_coordinates")
            require(target["coordinate_basis"] in {"requested", "delivered"},
                    "coordinate_basis_unspecified")
            context = target["measurement_context"]
            require(all(context.get(k) for k in ("method", "measurement_population",
                    "measurement_statistic", "statistical_unit")), "measurement_definition_incomplete")
            mean, sd = target["mean"], target["sd"]
            if mean is None:
                require(target["status"] in {"unsupported", "unavailable", "abstained"}
                        and sd is None and bool(target.get("reason")), "invalid_abstention")
            else:
                require(type(mean) in (float, int) and math.isfinite(mean), "invalid_prediction")
                require(target["status"] == "predicted", "numeric_prediction_status_mismatch")
                require(sd is None or type(sd) in (float, int) and math.isfinite(sd) and sd > 0,
                        "unsupported_zero_or_invalid_uncertainty")
                require(sd is not None or bool(target.get("uncertainty_limit")),
                        "unknown_uncertainty_limit_missing")
        rows = bundle.get("later_evidence", [])
        later_ids = _ids(rows)
        require(not set(initial_ids) & set(later_ids), "first_packet_cannot_be_rescored")
        candidates = {}
        for row in rows:
            key = row.get("specimen_id"), row.get("measurement_stage"), row.get("quantity")
            if key in by_target and row["evidence_id"] not in evidence_ids and not row.get("superseded"):
                candidates.setdefault(key, []).append(row["evidence_id"])
        result["ambiguous_targets"] = [
            {**dict(zip(("specimen_id", "measurement_stage", "quantity"), key)),
             "evidence_ids": ids, "reason": "precommitted_reduction_or_identity_required"}
            for key, ids in candidates.items() if len(ids) > 1]
        seen_targets = set()
        for row in rows:
            item = {"evidence_id": row["evidence_id"], "eligible": False}
            outcomes.append(item)
            # A complete physical packet also contains logs, aliquots and
            # unresolved stages. Keep them explicitly unscored; do not require
            # the owner to cherry-pick a forecast-only packet for this gate.
            key = row.get("specimen_id"), row.get("measurement_stage"), row.get("quantity")
            seen_targets.add(key)
            reason = None
            release = releases.get(row["delivery_id"], {})
            if row["evidence_id"] in evidence_ids:
                reason = "outcome_already_in_commitment_cutoff"
            elif row["origin"] != "physical":
                reason = "nonphysical_outcome"
            elif row.get("fixture_only") or row.get("rehearsal") or fixture:
                reason = "fixture_only_never_physical_score"
            elif row.get("superseded"):
                reason = "superseded_outcome"
            elif key not in by_target:
                reason = "uncommitted_specimen_stage_or_endpoint"
            elif len(candidates[key]) > 1:
                reason = "multiple_outcomes_require_precommitted_reduction_or_identity"
            elif _time(row.get("owner_received_at", row["received_at"])) <= committed:
                reason = "owner_received_before_commitment"
            elif _time(row["released_at"]) < _time(row["received_at"]):
                reason = "outcome_release_before_receipt"
            elif (not release.get("reviewer")
                  or release.get("released_at") != row["released_at"]):
                reason = "outcome_release_unreviewed"
            elif (row.get("earliest_known_at") is None
                  or not row.get("knowledge_chronology_reviewer")):
                reason = "outcome_knowledge_chronology_unreviewed"
            elif _time(row["earliest_known_at"]) <= committed:
                reason = "outcome_known_before_commitment"
            else:
                target = by_target[key]
                definition = measurement_definition_check(target, row)
                stage = measurement_stage_check(target, row)
                if stage["status"] != "matched":
                    reason = "measurement_stage_mismatch"
                elif definition["status"] != "matched":
                    reason = "measurement_definition_mismatch_or_unknown"
                elif target["unit"] != row["unit"]:
                    reason = "unit_mismatch_requires_attributed_conversion"
                elif row.get("value") is None:
                    reason = "outcome_unavailable"
                elif row.get("quality_status") in {"invalid", "unresolved", "rejected"}:
                    reason = "outcome_quality_unresolved"
                elif quality_review_exclusion(row) is not None:
                    reason = "outcome_quality_unresolved"
                    item["quality_review_exclusion"] = quality_review_exclusion(row)
                elif target["mean"] is None:
                    reason = "committed_abstention_retained_in_coverage"
                else:
                    item["eligible"] = True
                    item["prospectivity"] = "before_owner_receipt_and_reviewed_knowledge"
                    measured_at = row.get("measured_at")
                    if measured_at is not None:
                        item["prospectivity"] = (
                            "before_reported_measurement" if committed < _time(measured_at)
                            else "measurement_preexisted_commitment_but_was_not_known")
                    item["measurement_time_authenticated"] = False
            item["reason"] = reason
        result["missing_targets"] = [dict(zip(("specimen_id", "measurement_stage", "quantity"), key))
                                     for key in sorted(set(by_target) - seen_targets)]
        result["target_count"] = len(targets)
        result["waiting_for_later_outcomes"] = not bool(rows)
    except (KeyError, TypeError, ValueError, AttributeError, OverflowError) as exc:
        issues.append("malformed_or_unbound_record:" + type(exc).__name__ + ":" + str(exc))
    result["status"] = "rejected" if issues else "fixture_verified" if fixture else "boundary_verified"
    # An invalid global boundary cannot leave a row accidentally score-eligible.
    if issues:
        for row in outcomes:
            row["eligible"] = False
    result["structurally_eligible_outcome_count"] = sum(row["eligible"] for row in outcomes)
    result["native_records_authenticated"] = False
    result["physical_score_admissible"] = False
    result["remaining_assessment"] = [
        "Bind exports to native append-only decision and original execution bytes",
        "Independently replay the committed computation with original inputs",
        "Review original outcome receipts, numerical reductions and scientific applicability",
    ]
    return result



def validate_with_native(bundle, campaign_directory, execution_directories, *, pi_directory,
                         allow_fixture=False):
    """Reuse unchanged scientific native binding, then match the actual API tool call."""
    result = validate(bundle, campaign_directory=campaign_directory, pi_directory=pi_directory,
                      allow_fixture=allow_fixture)
    try:
        _need(hashlib.sha256(Path(legacy.__file__).read_bytes()).hexdigest() == LEGACY_SHA256,
              "legacy_native_verifier_changed")
        binding = legacy.verify_native_records(bundle, campaign_directory, execution_directories)
        result["native_binding"] = binding
        result["native_records_authenticated"] = True
        expected_id = binding["decision_call_id"]
        matched = [c for c in bundle["api_capture_prefix"]["accepted_tool_calls"]
                   if c["id"] == expected_id and c["name"] == "record_decision" and c["executable"]
                   and json.loads(c["arguments"]).get("rationale") == bundle["decision"]["rationale"]]
        _need(len(matched) == 1, "native_decision_call_not_bound_to_actual_api_response")
        result["remaining_assessment"] = result["remaining_assessment"][1:]
    except (ValueError, OSError, KeyError, TypeError, sqlite3.Error) as exc:
        result["issues"].append("native_binding_failed:" + str(exc))
        result["status"] = "rejected"
        result["native_records_authenticated"] = False
    result["api_route_prefix_authenticated"] = not bool(result["issues"])
    result["retained_base_identity_verified"] = False
    result["physical_score_admissible"] = False
    result["training_admission"] = False
    if result["issues"]:
        for row in result["outcomes"]:
            row["eligible"] = False
        result["structurally_eligible_outcome_count"] = 0
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("bundle", type=Path)
    parser.add_argument("--campaign", type=Path, required=True)
    parser.add_argument("--pi-directory", type=Path, required=True)
    parser.add_argument("--execution-dir", type=Path, action="append", default=[])
    parser.add_argument("--allow-fixture", action="store_true")
    args = parser.parse_args()
    result = validate_with_native(json.loads(args.bundle.read_text()), args.campaign,
                                  args.execution_dir, pi_directory=args.pi_directory,
                                  allow_fixture=args.allow_fixture)
    print(json.dumps(result, indent=2, allow_nan=False))
    return 1 if result["issues"] else 0


if __name__ == "__main__":
    raise SystemExit(main())
